COMMIT;

-- Kontrol sorgusu
SELECT
    COUNT(*) AS TOPLAM_KAYIT,
    SUM(CASE WHEN MUSTERITIPI = 1 THEN 1 ELSE 0 END) AS BIREYSEL_SAYISI,
    SUM(CASE WHEN MUSTERITIPI = 2 THEN 1 ELSE 0 END) AS KURUMSAL_SAYISI,
    COUNT(DISTINCT EPOSTA) AS BENZERSIZ_EPOSTA,
    COUNT(DISTINCT CASE WHEN MUSTERITIPI = 1 THEN TCKN END) AS BENZERSIZ_TCKN,
    COUNT(DISTINCT CASE WHEN MUSTERITIPI = 2 THEN VKN END) AS BENZERSIZ_VKN
FROM KB_MUSTERIBILGILERI
WHERE EPOSTA LIKE '%@test.com';

